def gen(rng):
    def fmt(b):
        return str(len(b)) + '\n' + '\n'.join('%d %d' % p for p in b)
    def seg(lo, hi, maxlen):
        s = rng.randint(lo, hi)
        return (s, min(10**9, s + rng.randint(0, maxlen)))
    tests = [fmt([(5, 5)]), fmt([(1, 6), (2, 8), (7, 12), (10, 16)]), fmt([(1, 2), (3, 4), (5, 6)]), fmt([(1, 3), (3, 5), (5, 7)]),
             fmt([(2, 2), (2, 2), (2, 2)]), fmt([(-10**9, 10**9), (-10**9, -10**9), (10**9, 10**9)]), fmt([(1, 10), (2, 3), (4, 5), (6, 7)])]
    for n in (2, 3, 4, 5, 6, 6, 6, 6):
        for _ in range(3):
            tests.append(fmt([seg(-6, 6, rng.randint(0, 5)) for _ in range(n)]))
    N = 5 * 10**4
    tests.append(fmt([seg(-10**9, 10**9, 10**8) for _ in range(2000)]))
    tests.append(fmt([seg(-10**9, 10**9 - 10**6, 10**6) for _ in range(N)]))
    tests.append(fmt([seg(-10**9, 10**9 - 5 * 10**4, 5 * 10**4) for _ in range(N)]))
    tests.append(fmt([(i * 10, i * 10 + 10) for i in range(N)]))
    tests.append(fmt([(i * 10, i * 10 + 9) for i in range(N)]))
    tests.append(fmt([(-10**9 + i, 10**9 - i) for i in range(N)]))
    return tests

